(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.03-t*0.4)*8 + Math.cos(my*0.025+t*0.3)*6;
  const w2y = Math.cos(my*0.028+t*0.35)*8 + Math.sin(mx*0.022-t*0.45)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+1)*40,0.14,2.1],
    [400+Math.cos(t*0.55+2)*70,200+Math.sin(t*0.75+4)*50,0.05,2.8]
  ];
  let aS=0,iS=0,crs=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    crs+=Math.sin(d*f*1.3-t*sp*0.4+0.8)*Math.cos(d*f*0.5+t*sp*0.8);
  }
  const act=aS/8,inh=iS/8,cross=crs/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.05+sy*0.01-t*0.6))/3+Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*2-t*2.1))*0.33;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2=Math.tanh((cross+act*inh*0.3-bg*0.2+spiral*0.5)*1.8);
  const feedback=Math.tanh(rd1*0.7+rd2*0.5+Math.sin(rd1*rd2*3+t)*0.3);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.2-sy*0.18+t*0.7)*0.3)*1.5)*0.3;
  const grain=Math.sin(sx*0.4+sy*0.35+t*3)*Math.sin(sx*0.35-sy*0.4-t*2.5)*0.06;
  const vig=1.0-Math.sqrt((x-cx)**2+(y-cy)**2)/320*0.25;
  const blend=(feedback*0.6+cell*0.25+grain+spiral*0.15)*vig;
  const v=blend*0.5+0.5;
  const pal=[[5,12,55],[10,38,88],[16,72,118],[24,118,128],[50,158,125],[120,188,98],[195,198,78],[228,162,68],[218,108,58],[178,62,55],[115,32,52],[55,16,48],[5,12,55]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(feedback*Math.PI)*0.15+Math.abs(rd2)*0.08;
  const edge=Math.abs(feedback)>0.75?1.14:(Math.abs(feedback)>0.5?1.06:1.0);
  return[
    Math.min(255,Math.max(0,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge))|0,
    Math.min(255,Math.max(0,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge))|0,
    Math.min(255,Math.max(0,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge))|0
  ];
}
